const fs=require('node:fs'),path=require('node:path'),http=require('node:http'),assert=require('node:assert/strict');
const {execFileSync}=require('node:child_process');
const {chromium}=require('playwright');
const posts=require('./search-recovery-content-20261109.cjs'),root=path.resolve(__dirname,'..'),remote=process.env.TEST_ORIGIN;
const server=http.createServer((req,res)=>{const u=new URL(req.url,'http://localhost');let file=path.resolve(root,'.'+decodeURIComponent(u.pathname));if(file!==root&&!file.startsWith(root+path.sep))return res.writeHead(403).end();if(fs.existsSync(file)&&fs.statSync(file).isDirectory())file=path.join(file,'index.html');if(!fs.existsSync(file))return res.writeHead(404).end();const ext=path.extname(file),mime={'.html':'text/html','.json':'application/json','.js':'text/javascript','.css':'text/css','.webp':'image/webp','.png':'image/png','.svg':'image/svg+xml','.txt':'text/plain'};res.writeHead(200,{'content-type':(/\.js_ver=/.test(file)?'text/javascript':mime[ext]||'application/octet-stream')+'; charset=utf-8'});fs.createReadStream(file).pipe(res)});
async function run(){if(!remote)await new Promise(r=>server.listen(0,'127.0.0.1',r));const origin=remote||'http://127.0.0.1:'+server.address().port,browser=await chromium.launch();try{const page=await browser.newPage(),bad=[],errors=[],rows=[];
 await page.route('**/*',r=>r.request().url().startsWith(origin)||r.request().url().startsWith('data:')?r.continue():r.abort());page.on('response',r=>{if(r.url().startsWith(origin)&&r.status()>=400)bad.push({url:r.url(),status:r.status()})});page.on('pageerror',e=>errors.push(e.message));
 for(const p of posts){const original=execFileSync('git',['show','38618c2:'+p.slug+'/index.html'],{cwd:root,encoding:'utf8'}),previous=await page.evaluate(html=>{const d=new DOMParser().parseFromString(html,'text/html');return {published:[...d.querySelectorAll('script[type="application/ld+json"]')].map(n=>JSON.parse(n.textContent)).find(s=>s['@type']==='BlogPosting').datePublished,images:[...d.images].map(n=>n.getAttribute('src'))}},original);
  for(const width of [320,390,1440]){await page.setViewportSize({width,height:1000});const response=await page.goto(origin+'/'+p.slug+'/',{waitUntil:'networkidle'});assert.equal(response.status(),200);
   const actual=await page.evaluate(()=>{const s=[...document.querySelectorAll('script[type="application/ld+json"]')].map(n=>JSON.parse(n.textContent)).find(s=>s['@type']==='BlogPosting'),body=document.querySelector('.detail-content');return {title:document.querySelector('h1').textContent,description:document.querySelector('meta[name="description"]').content,canonical:decodeURI(document.querySelector('link[rel="canonical"]').href),schema:s,images:[...document.images].map(n=>n.getAttribute('src')),broken:[...document.images].filter(i=>i.complete&&!i.naturalWidth).map(i=>i.src),overflow:document.documentElement.scrollWidth>innerWidth+1,faqs:body.querySelectorAll('[data-recovery-faq] h3').length,faqHeadings:[...body.querySelectorAll('h2')].filter(h=>h.textContent==='자주 묻는 질문').length,body:body.textContent,links:[...body.querySelectorAll('a[href]')].map(n=>n.getAttribute('href')),mainX:body.getBoundingClientRect().x,sideX:document.querySelector('.detail-side').getBoundingClientRect().x,sideY:document.querySelector('.detail-side').getBoundingClientRect().y}});
   assert.equal(actual.title,p.title);assert.equal(actual.description,p.description);assert.equal(actual.canonical,'https://4050guide.co.kr/'+p.slug+'/');assert.equal(actual.schema.datePublished,previous.published);assert.equal(actual.schema.dateModified,'2026-11-09');assert.equal(actual.schema.headline,p.title);assert.deepEqual(actual.images,previous.images);assert.equal(actual.faqs,3);assert.equal(actual.faqHeadings,1);assert(!actual.overflow,p.slug+' overflow '+width);assert.deepEqual(actual.broken,[]);assert(actual.body.includes('공식 자료와 확인일'));assert(actual.body.includes('2026년 11월 9일'));assert(!actual.body.includes('보완 2026-11-06'));
   if(width===1440)assert(actual.sideX>actual.mainX,'Sidebar is not on right');
   for(const link of actual.links.filter(u=>u.startsWith('/'))){const u=new URL(link,origin);let file=path.join(root,decodeURIComponent(u.pathname));if(fs.existsSync(file)&&fs.statSync(file).isDirectory())file=path.join(file,'index.html');assert(fs.existsSync(file),'Missing internal link '+link)}
   if(width===390||width===1440)await page.screenshot({path:path.resolve(root,'../4050-traffic-drop-audit-20261109/recovery-'+(remote?'live':'local')+'-'+p.slug+'-'+width+'.png')});rows.push({slug:p.slug,width,pass:true});
  }
  const download=await page.request.get(origin+'/assets/worksheets/'+p.slug+'.txt');assert.equal(download.status(),200);assert((await download.text()).includes(p.worksheet.split('\n')[0]));
 }
 for(const p of posts){const query=p.slug.startsWith('직업상담사')?'직업상담사 실기':p.slug.startsWith('내일배움카드')?'내일배움카드 훈련수당':p.slug.startsWith('폐업')?'경력증명서 대체서류':p.slug.startsWith('큐넷')?'큐넷 유효기간':'전기산업기사 경력증명서';await page.goto(origin+'/?s='+encodeURIComponent(query));const card=page.locator('.catalog-card').filter({has:page.locator('a[href="/'+p.slug+'/"]')});assert.equal(await card.count(),1);assert(await card.isVisible(),'Homepage search missing '+p.slug);assert((await card.innerText()).includes(p.title));}
 assert.deepEqual(bad,[]);assert.deepEqual(errors,[]);console.log(JSON.stringify({pass:true,origin,posts:posts.length,viewports:[320,390,1440],renders:rows.length,worksheets:5,searches:5,imagesAndPublishedDatesPreserved:true,bad,errors}));
 }finally{await browser.close();if(!remote)await new Promise(r=>server.close(r))}}
run().catch(e=>{console.error(e);process.exitCode=1});
